/** How many items, in order, fit in `available` with the gap between them, leaving room for a More trigger. */
function fitCount(widths: readonly number[], moreWidth: number, gap: number, available: number) {
  const total = widths.reduce((sum, width) => sum + width, 0) + gap * Math.max(0, widths.length - 1)
  if (total <= available) return widths.length
  let used = moreWidth
  let count = 0
  for (const width of widths) {
    if (used + gap + width > available) break
    used += gap + width
    count++
  }
  return count
}

function widthOf(element: Element | null) {
  return element?.getBoundingClientRect().width ?? 0
}

export { fitCount, widthOf }

"use client"

import type { ComponentProps, ReactElement } from "react"

import { NavigationMenuLink } from "@/components/ui/navigation-menu"
import { cn } from "@/lib/utils"

type SiteHeaderItem = {
  label: string
  /** Where the link goes. An item with `items` is a dropdown and needs none. */
  href?: string
  /** Marks the link for the current page with `aria-current="page"`. */
  current?: boolean
  /** A second line under the label, in a dropdown or the More panel. */
  description?: string
  /** Your router's link, like `<Link to="/pricing" />`. Wins over `renderLink`. */
  render?: ReactElement<Record<string, unknown>>
  /** Child links: the item becomes a dropdown. One level deep. */
  items?: readonly SiteHeaderItem[]
}

type SiteHeaderRenderLink = (item: SiteHeaderItem) => ReactElement<Record<string, unknown>> | undefined

function isCurrent(item: SiteHeaderItem): boolean {
  return Boolean(item.current) || (item.items?.some(isCurrent) ?? false)
}

// A router link brings its own href, and a second one on top could point somewhere else.
function linkTarget(item: SiteHeaderItem, renderLink: SiteHeaderRenderLink | undefined) {
  const render = item.render ?? renderLink?.(item)
  return render ? { render } : { href: item.href }
}

type PanelLinksProps = Omit<ComponentProps<"ul">, "children"> & {
  items: readonly SiteHeaderItem[]
  renderLink?: SiteHeaderRenderLink
}

function SiteHeaderPanelLinks({ items, renderLink, className, ...props }: PanelLinksProps) {
  return (
    <ul className={cn("m-0 flex list-none flex-col gap-px p-0", className)} {...props}>
      {items.map((item) => (
        <li key={item.label}>
          <NavigationMenuLink
            {...linkTarget(item, renderLink)}
            current={item.current}
            className="justify-center pointer-coarse:min-h-(--control-height-touch) data-current:bg-accent data-current:text-accent-foreground"
          >
            <span className="font-medium">{item.label}</span>
            {item.description && <span className="text-body-sm text-muted-foreground">{item.description}</span>}
          </NavigationMenuLink>
        </li>
      ))}
    </ul>
  )
}

export { isCurrent, linkTarget, SiteHeaderPanelLinks }
export type { SiteHeaderItem, SiteHeaderRenderLink }

"use client"

import { useId, useState } from "react"
import { MenuIcon, XIcon } from "lucide-react"

import { Drawer, DrawerBackdrop, DrawerClose, DrawerContent, DrawerTitle, DrawerTrigger } from "@/components/ui/drawer"
import {
  NavigationMenu,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
} from "@/components/ui/navigation-menu"
import {
  linkTarget,
  SiteHeaderPanelLinks,
  type SiteHeaderItem,
  type SiteHeaderRenderLink,
} from "@/components/ui/site-header-links"

type SiteHeaderDrawerProps = {
  label: string
  title: string
  items: readonly SiteHeaderItem[]
  renderLink?: SiteHeaderRenderLink
  menuLabel: string
  closeLabel: string
}

function SiteHeaderGroup({ item, renderLink }: { item: SiteHeaderItem; renderLink?: SiteHeaderRenderLink }) {
  const labelId = useId()
  return (
    <NavigationMenuItem className="flex w-full flex-col gap-inline not-first:pt-group not-last:pb-group">
      <span id={labelId} className="px-inset-item text-caption font-medium text-muted-foreground">
        {item.label}
      </span>
      <SiteHeaderPanelLinks items={item.items ?? []} renderLink={renderLink} aria-labelledby={labelId} />
    </NavigationMenuItem>
  )
}

function SiteHeaderDrawer({ label, title, items, renderLink, menuLabel, closeLabel }: SiteHeaderDrawerProps) {
  const [open, setOpen] = useState(false)
  return (
    <Drawer side="end" open={open} onOpenChange={setOpen}>
      <DrawerTrigger variant="ghost" size="icon" aria-label={menuLabel} className="hidden narrow:inline-flex">
        <MenuIcon />
      </DrawerTrigger>
      <DrawerBackdrop />
      <DrawerContent
        className="gap-group p-items"
        onClickCapture={(event) => {
          if (event.target instanceof Element && event.target.closest("a[href]")) setOpen(false)
        }}
      >
        <div className="flex items-center gap-inline">
          <DrawerTitle className="flex-1 truncate px-inset-item text-title-sm">{title}</DrawerTitle>
          <DrawerClose variant="ghost" size="icon" aria-label={closeLabel}>
            <XIcon />
          </DrawerClose>
        </div>
        <NavigationMenu aria-label={label} orientation="vertical" className="w-full max-w-none">
          <NavigationMenuList className="w-full gap-px">
            {items.map((item) =>
              item.items ? (
                <SiteHeaderGroup key={item.label} item={item} renderLink={renderLink} />
              ) : (
                <NavigationMenuItem key={item.label} className="w-full">
                  <NavigationMenuLink
                    {...linkTarget(item, renderLink)}
                    current={item.current}
                    variant="top"
                    className="w-full justify-start px-inset-item pointer-coarse:h-(--control-height-touch)"
                  >
                    {item.label}
                  </NavigationMenuLink>
                </NavigationMenuItem>
              ),
            )}
          </NavigationMenuList>
        </NavigationMenu>
      </DrawerContent>
    </Drawer>
  )
}

export { SiteHeaderDrawer }
export type { SiteHeaderDrawerProps }

"use client"

import type { ComponentProps, ReactNode } from "react"

import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuItemClassName,
} from "@/components/ui/navigation-menu"
import { SiteHeaderDrawer } from "@/components/ui/site-header-drawer"
import {
  isCurrent,
  linkTarget,
  SiteHeaderPanelLinks,
  type SiteHeaderItem,
  type SiteHeaderRenderLink,
} from "@/components/ui/site-header-links"
import { useOverflowCount, useScrolled } from "@/components/ui/use-site-header"
import { cn } from "@/lib/utils"

type SiteHeaderLabels = {
  /** The trigger that holds the links that don't fit. */
  more: string
  /** The narrow-screen button that opens every link in a drawer. */
  menu: string
  /** The drawer's close button. */
  close: string
}

const siteHeaderLabels: SiteHeaderLabels = { more: "More", menu: "Open menu", close: "Close menu" }

type SiteHeaderProps = Omit<ComponentProps<"header">, "children"> & {
  /** Names the `<nav>` landmark, like "Main". */
  label: string
  /** Usually a link to the home page with the logo. */
  brand?: ReactNode
  items: readonly SiteHeaderItem[]
  /** Calls to action at the end, like a Button to sign in. */
  actions?: ReactNode
  /** Turns every link into your router's, like `(item) => <Link to={item.href} />`. */
  renderLink?: SiteHeaderRenderLink
  moreLabel?: string
  menuLabel?: string
  closeLabel?: string
  /** The drawer's title on narrow screens. Defaults to `label`. */
  menuTitle?: string
}

// oxlint-disable-next-line shadcn/no-arbitrary-values -- sticks below the safe area, like Floating's top edge
const stickyClassName = "sticky top-[calc(var(--floating-offset)+env(safe-area-inset-top))]"

// The floating fill and shadow, one step stronger: more opaque, and the floating shadow laid twice, so flat stays flat.
const scrolledClassName = [
  "group-data-scrolled/site-header:bg-[color-mix(in_oklab,var(--popover)_min(100%,calc(var(--floating-opacity)+10%)),transparent)]",
  "group-data-scrolled/site-header:shadow-[var(--floating-shadow),var(--floating-shadow)]",
].join(" ")

const triggerCurrentClassName = "data-current:bg-accent data-current:text-accent-foreground"

function Chevron() {
  return <span aria-hidden="true" className="size-3 shrink-0" />
}

function BarItem({ item, renderLink }: { item: SiteHeaderItem; renderLink?: SiteHeaderRenderLink }) {
  if (!item.items) {
    return (
      <NavigationMenuItem>
        <NavigationMenuLink
          {...linkTarget(item, renderLink)}
          current={item.current}
          variant="top"
          className="touch-target"
        >
          {item.label}
        </NavigationMenuLink>
      </NavigationMenuItem>
    )
  }
  return (
    <NavigationMenuItem value={item.label}>
      <NavigationMenuTrigger
        data-current={isCurrent(item) ? "" : undefined}
        className={cn("touch-target", triggerCurrentClassName)}
      >
        {item.label}
      </NavigationMenuTrigger>
      <NavigationMenuContent sideOffset={8}>
        <SiteHeaderPanelLinks items={item.items} renderLink={renderLink} className="w-64" />
      </NavigationMenuContent>
    </NavigationMenuItem>
  )
}

function MorePanel({ items, renderLink }: { items: readonly SiteHeaderItem[]; renderLink?: SiteHeaderRenderLink }) {
  const links = items.filter((item) => !item.items)
  const groups = items.filter((item) => item.items)
  return (
    <div className="flex w-64 flex-col gap-group">
      {links.length > 0 && <SiteHeaderPanelLinks items={links} renderLink={renderLink} />}
      {groups.map((group) => (
        <div key={group.label} className="flex flex-col gap-inline">
          <span className="px-inset-item text-caption font-medium text-muted-foreground">{group.label}</span>
          <SiteHeaderPanelLinks items={group.items ?? []} renderLink={renderLink} aria-label={group.label} />
        </div>
      ))}
    </div>
  )
}

function SiteHeader({
  label,
  brand,
  items,
  actions,
  renderLink,
  moreLabel = siteHeaderLabels.more,
  menuLabel = siteHeaderLabels.menu,
  closeLabel = siteHeaderLabels.close,
  menuTitle,
  className,
  ...props
}: SiteHeaderProps) {
  const { containerRef, measureRef, count } = useOverflowCount()
  const { sentinelRef, scrolled } = useScrolled()
  const shown = count === null ? items : items.slice(0, count)
  const hidden = count === null ? [] : items.slice(count)

  return (
    <>
      <span ref={sentinelRef} aria-hidden="true" data-slot="site-header-sentinel" className="absolute size-px" />
      <header
        data-slot="site-header"
        data-scrolled={scrolled ? "" : undefined}
        className={cn(
          "group/site-header pointer-events-none z-sticky flex w-full justify-center px-floating",
          stickyClassName,
          className,
        )}
        {...props}
      >
        <div
          data-slot="site-header-bar"
          className={cn(
            "pointer-events-auto flex w-full max-w-(--site-header-width,64rem) min-w-0 items-center gap-items surface-floating p-inline transition duration-panel ease-standard",
            scrolledClassName,
          )}
        >
          {brand !== undefined && (
            <div data-slot="site-header-brand" className="flex shrink-0 items-center ps-(--item-padding-x)">
              {brand}
            </div>
          )}
          <div ref={containerRef} data-slot="site-header-nav" className="relative min-w-0 flex-1 narrow:hidden">
            <NavigationMenu
              aria-label={label}
              data-measured={count === null ? undefined : ""}
              className="w-full max-w-none justify-center not-data-measured:overflow-hidden"
            >
              <NavigationMenuList>
                {shown.map((item) => (
                  <BarItem key={item.label} item={item} renderLink={renderLink} />
                ))}
                {hidden.length > 0 && (
                  <NavigationMenuItem value="more">
                    <NavigationMenuTrigger
                      data-current={hidden.some(isCurrent) ? "" : undefined}
                      className={cn("touch-target", triggerCurrentClassName)}
                    >
                      {moreLabel}
                    </NavigationMenuTrigger>
                    <NavigationMenuContent sideOffset={8} align="end">
                      <MorePanel items={hidden} renderLink={renderLink} />
                    </NavigationMenuContent>
                  </NavigationMenuItem>
                )}
              </NavigationMenuList>
            </NavigationMenu>
            <div
              ref={measureRef}
              aria-hidden="true"
              inert
              data-slot="site-header-measure"
              className="pointer-events-none invisible absolute start-0 top-0 flex w-max gap-inline"
            >
              {items.map((item) => (
                <span key={item.label} data-slot="site-header-measure-item" className={navigationMenuItemClassName}>
                  {item.label}
                  {item.items && <Chevron />}
                </span>
              ))}
              <span data-slot="site-header-measure-more" className={navigationMenuItemClassName}>
                {moreLabel}
                <Chevron />
              </span>
            </div>
          </div>
          {actions !== undefined && (
            <div data-slot="site-header-actions" className="ms-auto flex shrink-0 items-center gap-items">
              {actions}
            </div>
          )}
          <SiteHeaderDrawer
            label={label}
            title={menuTitle ?? label}
            items={items}
            renderLink={renderLink}
            menuLabel={menuLabel}
            closeLabel={closeLabel}
          />
        </div>
      </header>
    </>
  )
}

export { SiteHeader, siteHeaderLabels }
export type { SiteHeaderItem, SiteHeaderLabels, SiteHeaderProps, SiteHeaderRenderLink }

"use client"

import { useEffect, useRef, useState } from "react"

import { fitCount, widthOf } from "@/components/ui/site-header-overflow"

/**
 * Measures a hidden row of item copies against the space their container offers. It observes sizes, never scroll
 * or window resize, so it also reacts to fonts loading and to siblings growing.
 */
function useOverflowCount() {
  const containerRef = useRef<HTMLDivElement>(null)
  const measureRef = useRef<HTMLDivElement>(null)
  const [count, setCount] = useState<number | null>(null)

  useEffect(() => {
    const container = containerRef.current
    const measure = measureRef.current
    if (!container || !measure || typeof ResizeObserver !== "function") return
    const observer = new ResizeObserver(() => {
      const items = [...measure.querySelectorAll('[data-slot="site-header-measure-item"]')].map(widthOf)
      const more = widthOf(measure.querySelector('[data-slot="site-header-measure-more"]'))
      const gap = Number.parseFloat(getComputedStyle(measure).columnGap) || 0
      setCount(fitCount(items, more, gap, widthOf(container)))
    })
    observer.observe(container)
    observer.observe(measure)
    return () => observer.disconnect()
  }, [])

  return { containerRef, measureRef, count }
}

/** Whether the 1px sentinel the header renders has left the viewport, so the page scrolled under the header. */
function useScrolled() {
  const sentinelRef = useRef<HTMLSpanElement>(null)
  const [scrolled, setScrolled] = useState(false)
  useEffect(() => {
    const sentinel = sentinelRef.current
    if (!sentinel || typeof IntersectionObserver !== "function") return
    const observer = new IntersectionObserver(([entry]) => setScrolled(entry ? !entry.isIntersecting : false))
    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [])
  return { sentinelRef, scrolled }
}

export { useOverflowCount, useScrolled }
